//! Generate the api-set resolver table from the checked-in C table at build
//! time — self-hosting the old `tools/gen_apisets_rs.py` step (no committed
//! `src/apisets_table.rs`).
//!
//! `sdk/lib/apisets/apisets.table.c` is an autogenerated-but-checked-in C array
//! of `{ RTL_CONSTANT_STRING(L"name"), RTL_CONSTANT_STRING(L"target"), FLAGS }`.
//! We parse each entry and emit `$OUT_DIR/apisets_table.rs` (per-entry `[u16;N]`
//! name/target statics + the `G_APISETS` array), which `src/apisets.rs`
//! `include!`s inside a module that supplies `us` / `RosApiset`. The api-set
//! data is identical for every arch/feature build, so this runs per build dir.

use std::{env, fs, path::PathBuf};

/// APISET_* flag bits (apisets.h / apisetsp.h).
fn parse_flags(expr: &str) -> u32 {
    let mut v = 0u32;
    for tok in expr.split('|') {
        v |= match tok.trim() {
            "APISET_WIN7" => 1,
            "APISET_WIN8" => 2,
            "APISET_WIN81" => 4,
            "APISET_WIN10" => 8,
            other => panic!("unknown apiset flag token: {other:?}"),
        };
    }
    v
}

/// UTF-16LE code units + NUL terminator → a Rust `[u16; N]` initializer.
fn u16_array(s: &str) -> (usize, String) {
    let mut units: Vec<u16> = s.encode_utf16().collect();
    units.push(0);
    let body = units
        .iter()
        .map(|u| format!("0x{u:04x}"))
        .collect::<Vec<_>>()
        .join(", ");
    (units.len(), format!("[{body}]"))
}

fn main() {
    let manifest = PathBuf::from(env::var("CARGO_MANIFEST_DIR").unwrap());
    // sdk/lib/rust/ntdll-rust -> ../../apisets/apisets.table.c = sdk/lib/apisets/…
    let table_c = manifest.join("../../apisets/apisets.table.c");
    println!("cargo:rerun-if-changed={}", table_c.display());
    let src = fs::read_to_string(&table_c)
        .unwrap_or_else(|e| panic!("read {}: {e}", table_c.display()));

    // Each entry is one `{ RTL_CONSTANT_STRING(L"NAME"),
    // RTL_CONSTANT_STRING(L"TARGET"), FLAGS },` line.
    let mut entries: Vec<(String, String, u32)> = Vec::new();
    for line in src.lines() {
        let line = line.trim();
        if !line.starts_with('{') || !line.contains("RTL_CONSTANT_STRING") {
            continue;
        }
        let i1 = line.find("L\"").expect("name L\"") + 2;
        let n_end = line[i1..].find('"').expect("name end") + i1;
        let name = line[i1..n_end].to_string();
        let rest = &line[n_end + 1..];
        let i2 = rest.find("L\"").expect("target L\"") + 2;
        let t_end = rest[i2..].find('"').expect("target end") + i2;
        let target = rest[i2..t_end].to_string();
        let after = &rest[t_end..];
        let brace = after.find('}').expect("entry close brace");
        let seg = &after[..brace]; // `"), FLAGS `
        let comma = seg.find(',').expect("flags comma");
        let flags = parse_flags(seg[comma + 1..].trim());
        entries.push((name, target, flags));
    }
    assert!(!entries.is_empty(), "no apiset entries parsed from {}", table_c.display());

    // Body only — no inner attrs / `use` (the include site's wrapper module
    // supplies `use super::{us, RosApiset}` and an outer `#[allow(clippy::all)]`).
    let mut out = String::new();
    out.push_str("// @generated by ntdll-rust/build.rs from sdk/lib/apisets/apisets.table.c\n");
    for (i, (name, target, _)) in entries.iter().enumerate() {
        let (nl, na) = u16_array(name);
        let (tl, ta) = u16_array(target);
        out.push_str(&format!("static N{i}: [u16; {nl}] = {na};\n"));
        out.push_str(&format!("static T{i}: [u16; {tl}] = {ta};\n"));
    }
    out.push('\n');
    out.push_str(&format!(
        "pub(super) static G_APISETS: [RosApiset; {}] = [\n",
        entries.len()
    ));
    for (i, (_, _, flags)) in entries.iter().enumerate() {
        out.push_str(&format!(
            "    RosApiset {{ name: us(&N{i}), target: us(&T{i}), dw_os_versions: 0x{flags:x} }},\n"
        ));
    }
    out.push_str("];\n");

    let out_dir = PathBuf::from(env::var("OUT_DIR").unwrap());
    fs::write(out_dir.join("apisets_table.rs"), out)
        .unwrap_or_else(|e| panic!("write apisets_table.rs: {e}"));
}
